using System;
using System.Collections.Generic;
using System.Text;

namespace NESOOP.Compiler
{
    public sealed class Nes6502CodeGenerator
    {
        private const string ExpressionTemp =
            "__nesoop_expr_temp";


        public string Generate(
            SemanticProgram program
        )
        {
            StringBuilder output = new();


            output.AppendLine(
                "; =========================================================="
            );

            output.AppendLine(
                "; GENERATED BY NesOop.Compiler"
            );

            output.AppendLine(
                "; DO NOT EDIT MANUALLY"
            );

            output.AppendLine(
                "; =========================================================="
            );

            output.AppendLine();


            // =========================================================
            // RAM
            // =========================================================

            output.AppendLine(
                ".segment \"BSS\""
            );

            output.AppendLine();


            // Temporary byte used while evaluating expressions.
            output.AppendLine(
                $"{ExpressionTemp}: .res 1"
            );


            foreach (
                SemanticByteDeclaration variable
                in program.Statements
                    .OfType<SemanticByteDeclaration>()
            )
            {
                output.AppendLine(
                    $"{variable.StorageName}: .res 1"
                );
            }


            output.AppendLine();


            // =========================================================
            // CODE
            // =========================================================

            output.AppendLine(
                ".segment \"CODE\""
            );

            output.AppendLine();

            output.AppendLine(
                ".export Game_Start"
            );

            output.AppendLine();

            output.AppendLine(
                ".proc Game_Start"
            );

            output.AppendLine();


            foreach (
                SemanticStatement statement
                in program.Statements
            )
            {
                GenerateStatement(
                    output,
                    statement
                );
            }


            output.AppendLine(
                "    rts"
            );

            output.AppendLine();

            output.AppendLine(
                ".endproc"
            );


            return output.ToString();
        }


        private static void GenerateStatement(
            StringBuilder output,
            SemanticStatement statement
        )
        {
            // =========================================================
            // byte variable = expression;
            // =========================================================

            if (
                statement
                is SemanticByteDeclaration variable
            )
            {
                output.AppendLine(
                    $"    ; byte {variable.Name}"
                );


                GenerateLoadValue(
                    output,
                    variable.Initializer
                );


                output.AppendLine(
                    $"    sta {variable.StorageName}"
                );

                output.AppendLine();

                return;
            }


            // =========================================================
            // variable = expression;
            // =========================================================

            if (
                statement
                is SemanticVariableAssignment assignment
            )
            {
                output.AppendLine(
                    "    ; variable assignment"
                );


                GenerateLoadValue(
                    output,
                    assignment.Value
                );


                output.AppendLine(
                    $"    sta {assignment.StorageName}"
                );

                output.AppendLine();

                return;
            }


            // =========================================================
            // Screen.BackgroundColor = expression;
            // =========================================================

            if (
                statement
                is SemanticBackgroundColorAssignment background
            )
            {
                output.AppendLine(
                    "    ; Screen.BackgroundColor"
                );


                // Reset PPU address latch
                output.AppendLine(
                    "    lda $2002"
                );

                output.AppendLine();


                // Select palette address $3F00
                output.AppendLine(
                    "    lda #$3F"
                );

                output.AppendLine(
                    "    sta $2006"
                );

                output.AppendLine();

                output.AppendLine(
                    "    lda #$00"
                );

                output.AppendLine(
                    "    sta $2006"
                );

                output.AppendLine();


                GenerateLoadValue(
                    output,
                    background.Value
                );


                // NES palette values are six bits.
                output.AppendLine(
                    "    and #$3F"
                );


                output.AppendLine(
                    "    sta $2007"
                );

                output.AppendLine();

                return;
            }


            throw new Exception(
                "Internal compiler error: " +
                "unknown semantic statement."
            );
        }


        private static void GenerateLoadValue(
            StringBuilder output,
            SemanticValue value
        )
        {
            switch (value)
            {
                // -----------------------------------------------------
                // Literal
                // -----------------------------------------------------

                case SemanticByteLiteral literal:

                    output.AppendLine(
                        $"    lda #${literal.Value:X2}"
                    );

                    return;


                // -----------------------------------------------------
                // Variable
                // -----------------------------------------------------

                case SemanticVariableReference variable:

                    output.AppendLine(
                        $"    lda {variable.StorageName}"
                    );

                    return;


                // -----------------------------------------------------
                // Addition
                // -----------------------------------------------------

                case SemanticBinaryAdd add:

                    // Evaluate left side into A.
                    GenerateLoadValue(
                        output,
                        add.Left
                    );


                    // Preserve it on the CPU stack.
                    output.AppendLine(
                        "    pha"
                    );


                    // Evaluate right side into A.
                    GenerateLoadValue(
                        output,
                        add.Right
                    );


                    // Temporarily preserve right side.
                    output.AppendLine(
                        $"    sta {ExpressionTemp}"
                    );


                    // Restore left side.
                    output.AppendLine(
                        "    pla"
                    );


                    // A = left + right
                    output.AppendLine(
                        "    clc"
                    );

                    output.AppendLine(
                        $"    adc {ExpressionTemp}"
                    );


                    return;


                default:

                    throw new Exception(
                        "Internal compiler error: " +
                        "cannot load semantic value."
                    );
            }
        }
    }
}
